//! The `clipboard` capability: reading the current copy, writing text, a URL or files, and
//! watching for new copies.
//!
//! Reading and watching need macOS to let Dupin paste from other apps without asking, the
//! same pasteboard policy clipboard history needs. Writing needs no OS permission but, like
//! reading, a host-verified user activation. Copies marked concealed, transient or
//! auto-generated, and copies from an ignored app, are never read: a read or watch sees
//! nothing for them. A watch is a host-side subscription to the native clipboard monitor, so
//! the guest is called on each change rather than polling. Keeping a history is the
//! extension's job, through its `storage` capability.

use std::path::{Component, Path, PathBuf};
use std::sync::{Arc, Mutex, Weak};

use dupin_broker::{OsAccess, OsPermission, Trigger};
use serde::{Serialize, Serializer};

use crate::service::ServiceError;

pub const MAX_TEXT_BYTES: usize = 1024 * 1024;
pub const MAX_URL_BYTES: usize = 8192;
pub const MAX_FILES: usize = 64;
pub const MAX_PATH_BYTES: usize = 4096;
pub const MAX_IMAGE_BYTES: usize = 2 * 1024 * 1024;

/// Reading and watching need this; writing needs none.
pub const PERMISSION: OsPermission = OsPermission::Pasteboard;

/// Markers password managers and clipboard tools put on a copy to keep it out of other
/// tools ([nspasteboard.org](http://nspasteboard.org)).
pub const WITHHELD_TYPES: [&str; 3] = [
    "org.nspasteboard.ConcealedType",
    "org.nspasteboard.TransientType",
    "org.nspasteboard.AutoGeneratedType",
];
/// The bundle ID of the app a copy declares it came from.
pub const SOURCE_TYPE: &str = "org.nspasteboard.source";

/// Whether a copy with these pasteboard types must not be read.
pub fn withheld(types: &[String]) -> bool {
    types.iter().any(|kind| WITHHELD_TYPES.contains(&kind.as_str()))
}

#[derive(Clone, Debug, PartialEq, Eq, Serialize)]
#[serde(tag = "type", rename_all = "kebab-case")]
pub enum Content {
    Text {
        text: String,
    },
    Url {
        url: String,
    },
    Files {
        files: Vec<FileRef>,
    },
    #[serde(rename_all = "camelCase")]
    Image {
        /// `image/png` or `image/tiff`.
        media_type: String,
        /// Base64 when serialized.
        #[serde(serialize_with = "base64")]
        data: Vec<u8>,
    },
}

#[derive(Clone, Debug, PartialEq, Eq, Serialize)]
pub struct FileRef {
    pub path: String,
    pub name: String,
}

impl FileRef {
    pub fn new(path: &Path) -> Self {
        Self {
            path: path.to_string_lossy().into_owned(),
            name: path
                .file_name()
                .unwrap_or(path.as_os_str())
                .to_string_lossy()
                .into_owned(),
        }
    }
}

fn base64<S: Serializer>(data: &[u8], serializer: S) -> Result<S::Ok, S::Error> {
    use base64::Engine;
    serializer.serialize_str(&base64::engine::general_purpose::STANDARD.encode(data))
}

/// One copy, with the pasteboard change it was read from.
#[derive(Clone, Debug, PartialEq, Eq, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct Clip {
    pub change: i64,
    pub content: Content,
}

/// What a guest may put on the clipboard, validated.
#[derive(Clone, Debug, PartialEq, Eq)]
pub enum Write {
    Text(String),
    Url(String),
    Files(Vec<PathBuf>),
}

impl Write {
    pub fn text(text: String) -> Result<Self, ServiceError> {
        if text.is_empty() || text.len() > MAX_TEXT_BYTES {
            return Err(ServiceError::Invalid(format!("text is 1–{MAX_TEXT_BYTES} bytes")));
        }
        Ok(Self::Text(text))
    }

    pub fn url(url: String) -> Result<Self, ServiceError> {
        let scheme = url.split_once(':').map(|(scheme, _)| scheme).unwrap_or_default();
        let valid = url.len() <= MAX_URL_BYTES
            && scheme.starts_with(|c: char| c.is_ascii_alphabetic())
            && scheme
                .bytes()
                .all(|b| b.is_ascii_alphanumeric() || b"+.-".contains(&b))
            && !url.contains(|c: char| c.is_whitespace() || c.is_control());
        if !valid {
            return Err(ServiceError::Invalid(format!(
                "a URL is absolute, at most {MAX_URL_BYTES} bytes, with no spaces"
            )));
        }
        Ok(Self::Url(url))
    }

    pub fn files(paths: Vec<PathBuf>) -> Result<Self, ServiceError> {
        if paths.is_empty() || paths.len() > MAX_FILES {
            return Err(ServiceError::Invalid(format!("name 1–{MAX_FILES} files")));
        }
        let valid = |path: &PathBuf| {
            path.is_absolute()
                && path.as_os_str().len() <= MAX_PATH_BYTES
                && !path.to_string_lossy().contains('\0')
                && path
                    .components()
                    .all(|component| matches!(component, Component::RootDir | Component::Normal(_)))
        };
        if !paths.iter().all(valid) {
            return Err(ServiceError::Invalid(format!(
                "a file is an absolute path of at most {MAX_PATH_BYTES} bytes, with no `..`"
            )));
        }
        Ok(Self::Files(paths))
    }
}

/// What the pasteboard holds, read without its contents.
#[derive(Clone, Debug, Default, PartialEq, Eq)]
pub struct Peek {
    pub change: i64,
    pub types: Vec<String>,
    /// Bundle IDs of the apps that were frontmost around the copy.
    pub apps: Vec<String>,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Limits {
    pub text_bytes: usize,
    pub image_bytes: usize,
    pub files: usize,
}

/// Ends a watch when dropped.
pub struct Watch {
    _guard: Box<dyn Send + Sync>,
}

impl Watch {
    pub fn new(guard: impl Send + Sync + 'static) -> Self {
        Self {
            _guard: Box::new(guard),
        }
    }
}

/// The system clipboard: the general pasteboard on macOS, [`Fixture`] in tests.
pub trait Pasteboard: Send + Sync {
    /// Whether Dupin may read without the system's paste prompt, checked without reading.
    fn access(&self) -> OsAccess;
    /// The change count, types and frontmost apps, without reading any contents.
    fn peek(&self) -> Peek;
    /// The app the copy declares as its source, if it declares one.
    fn source(&self) -> Option<String>;
    /// The contents, or `None` when the pasteboard has changed since `change`, holds nothing
    /// readable or holds more than `limits` allow.
    fn read(&self, change: i64, limits: &Limits) -> Option<Content>;
    fn write(&self, content: &Write) -> Result<(), ServiceError>;
    /// Calls `changed` on each new copy, from the monitor's thread, until the watch is dropped.
    fn watch(&self, changed: Box<dyn Fn(Peek) + Send + Sync>) -> Result<Watch, ServiceError>;
}

impl<P: Pasteboard + ?Sized> Pasteboard for Arc<P> {
    fn access(&self) -> OsAccess {
        (**self).access()
    }
    fn peek(&self) -> Peek {
        (**self).peek()
    }
    fn source(&self) -> Option<String> {
        (**self).source()
    }
    fn read(&self, change: i64, limits: &Limits) -> Option<Content> {
        (**self).read(change, limits)
    }
    fn write(&self, content: &Write) -> Result<(), ServiceError> {
        (**self).write(content)
    }
    fn watch(&self, changed: Box<dyn Fn(Peek) + Send + Sync>) -> Result<Watch, ServiceError> {
        (**self).watch(changed)
    }
}

/// What the user configured for clipboard history, which extensions follow too.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Policy {
    pub ignored_apps: Vec<String>,
    pub max_text_bytes: usize,
}

impl Default for Policy {
    fn default() -> Self {
        Self {
            ignored_apps: Vec::new(),
            max_text_bytes: MAX_TEXT_BYTES,
        }
    }
}

struct Inner<P> {
    board: P,
    policy: Mutex<Policy>,
}

pub struct Clipboard<P> {
    inner: Arc<Inner<P>>,
}

impl<P: Pasteboard + 'static> Clipboard<P> {
    pub fn new(board: P, policy: Policy) -> Self {
        Self {
            inner: Arc::new(Inner {
                board,
                policy: Mutex::new(policy),
            }),
        }
    }

    pub fn set_policy(&self, policy: Policy) {
        *self.inner.policy.lock().unwrap() = policy;
    }

    /// The current copy, or `None` for an empty, withheld, ignored or oversized one.
    pub fn read(&self, trigger: Trigger) -> Result<Option<Clip>, ServiceError> {
        if trigger != Trigger::Activation {
            return Err(ServiceError::NeedsActivation);
        }
        self.inner.allowed()?;
        Ok(self.inner.capture(self.inner.board.peek()))
    }

    pub fn write(&self, trigger: Trigger, content: &Write) -> Result<(), ServiceError> {
        if trigger != Trigger::Activation {
            return Err(ServiceError::NeedsActivation);
        }
        self.inner.board.write(content)
    }

    /// Calls `deliver` with each new copy that may be read, until the watch is dropped.
    pub fn watch(&self, deliver: impl Fn(Clip) + Send + Sync + 'static) -> Result<Watch, ServiceError> {
        self.inner.allowed()?;
        let inner: Weak<Inner<P>> = Arc::downgrade(&self.inner);
        self.inner.board.watch(Box::new(move |peek| {
            if let Some(inner) = inner.upgrade()
                && inner.allowed().is_ok()
                && let Some(clip) = inner.capture(peek)
            {
                deliver(clip);
            }
        }))
    }
}

impl<P: Pasteboard> Inner<P> {
    fn allowed(&self) -> Result<(), ServiceError> {
        ServiceError::from_access(PERMISSION, self.board.access()).map_or(Ok(()), Err)
    }

    fn capture(&self, peek: Peek) -> Option<Clip> {
        if withheld(&peek.types) {
            return None;
        }
        let policy = self.policy.lock().unwrap().clone();
        let ignored = |app: &str| policy.ignored_apps.iter().any(|ignored| ignored == app);
        if peek.apps.iter().any(|app| ignored(app)) {
            return None;
        }
        if peek.types.iter().any(|kind| kind == SOURCE_TYPE)
            && self.board.source().is_some_and(|source| ignored(&source))
        {
            return None;
        }
        let limits = Limits {
            text_bytes: policy.max_text_bytes.min(MAX_TEXT_BYTES),
            image_bytes: MAX_IMAGE_BYTES,
            files: MAX_FILES,
        };
        let content = self.board.read(peek.change, &limits)?;
        Some(Clip {
            change: peek.change,
            content,
        })
    }
}

type Watcher = Arc<dyn Fn(Peek) + Send + Sync>;

#[derive(Default)]
struct FixtureState {
    access: Option<OsAccess>,
    peek: Peek,
    source: Option<String>,
    content: Option<Content>,
    reads: usize,
    written: Vec<Write>,
}

/// An in-memory pasteboard. Copies notify watches synchronously.
#[derive(Default)]
pub struct Fixture {
    state: Mutex<FixtureState>,
    watchers: Arc<Mutex<Vec<(u64, Watcher)>>>,
    next: Mutex<u64>,
}

impl Fixture {
    pub fn new(access: OsAccess) -> Self {
        let fixture = Self::default();
        fixture.set_access(access);
        fixture
    }

    pub fn set_access(&self, access: OsAccess) {
        self.state.lock().unwrap().access = Some(access);
    }

    /// Puts a copy on the pasteboard, as `app` copying it with `types` beside its own.
    pub fn copy(&self, content: Content, types: &[&str], app: Option<&str>, source: Option<&str>) {
        let peek = {
            let mut state = self.state.lock().unwrap();
            let change = state.peek.change + 1;
            let mut all: Vec<String> = types.iter().map(|kind| (*kind).to_owned()).collect();
            if source.is_some() {
                all.push(SOURCE_TYPE.into());
            }
            state.peek = Peek {
                change,
                types: all,
                apps: app.into_iter().map(str::to_owned).collect(),
            };
            state.source = source.map(str::to_owned);
            state.content = Some(content);
            state.peek.clone()
        };
        let watchers: Vec<Watcher> = self
            .watchers
            .lock()
            .unwrap()
            .iter()
            .map(|(_, watcher)| watcher.clone())
            .collect();
        for watcher in watchers {
            watcher(peek.clone());
        }
    }

    /// How many times the contents were read.
    pub fn reads(&self) -> usize {
        self.state.lock().unwrap().reads
    }

    pub fn written(&self) -> Vec<Write> {
        self.state.lock().unwrap().written.clone()
    }

    pub fn watches(&self) -> usize {
        self.watchers.lock().unwrap().len()
    }
}

impl Pasteboard for Fixture {
    fn access(&self) -> OsAccess {
        self.state
            .lock()
            .unwrap()
            .access
            .unwrap_or(OsAccess::NotDetermined)
    }

    fn peek(&self) -> Peek {
        self.state.lock().unwrap().peek.clone()
    }

    fn source(&self) -> Option<String> {
        self.state.lock().unwrap().source.clone()
    }

    fn read(&self, change: i64, limits: &Limits) -> Option<Content> {
        let mut state = self.state.lock().unwrap();
        state.reads += 1;
        if state.peek.change != change {
            return None;
        }
        let content = state.content.clone()?;
        let fits = match &content {
            Content::Text { text } => text.len() <= limits.text_bytes,
            Content::Url { url } => url.len() <= MAX_URL_BYTES,
            Content::Files { files } => files.len() <= limits.files,
            Content::Image { data, .. } => data.len() <= limits.image_bytes,
        };
        fits.then_some(content)
    }

    fn write(&self, content: &Write) -> Result<(), ServiceError> {
        let mut state = self.state.lock().unwrap();
        state.written.push(content.clone());
        state.peek = Peek {
            change: state.peek.change + 1,
            ..Peek::default()
        };
        state.source = None;
        state.content = Some(match content {
            Write::Text(text) => Content::Text { text: text.clone() },
            Write::Url(url) => Content::Url { url: url.clone() },
            Write::Files(paths) => Content::Files {
                files: paths.iter().map(|path| FileRef::new(path)).collect(),
            },
        });
        Ok(())
    }

    fn watch(&self, changed: Box<dyn Fn(Peek) + Send + Sync>) -> Result<Watch, ServiceError> {
        let id = {
            let mut next = self.next.lock().unwrap();
            *next += 1;
            *next
        };
        self.watchers.lock().unwrap().push((id, Arc::from(changed)));
        Ok(Watch::new(Unwatch {
            watchers: Arc::downgrade(&self.watchers),
            id,
        }))
    }
}

struct Unwatch {
    watchers: Weak<Mutex<Vec<(u64, Watcher)>>>,
    id: u64,
}

impl Drop for Unwatch {
    fn drop(&mut self) {
        if let Some(watchers) = self.watchers.upgrade() {
            watchers.lock().unwrap().retain(|(id, _)| *id != self.id);
        }
    }
}

